/**
 * Кубоход: the complete, deterministic campaign and shared puzzle rules.
 * Orientations: 0 upright, 1 lying across X, 2 lying across Y.
 * Tile coordinates include bridge cells; bridges override their support.
 */
export const DIRECTIONS = Object.freeze(['up', 'right', 'down', 'left']);

export function occupied(state) {
  const { x, y, o } = state;
  return o === 1 ? [[x, y], [x + 1, y]] : o === 2 ? [[x, y], [x, y + 1]] : [[x, y]];
}

const cache = new WeakMap();
const cellKey = (x, y) => `${x},${y}`;
const stateKey = s => `${s.x},${s.y},${s.o},${s.mask || 0}`;

function geometry(level) {
  let data = cache.get(level);
  if (!data) {
    data = {
      tiles: new Set(level.tiles.map(([x, y]) => cellKey(x, y))),
      fragile: new Set((level.fragile || []).map(([x, y]) => cellKey(x, y))),
      bridges: new Map((level.bridges || []).map(b => [cellKey(...b.at), b.bit])),
    };
    cache.set(level, data);
  }
  return data;
}

/** Return the resulting state, or null for falling off / breaking a tile. */
export function move(level, state, direction) {
  let { x, y, o } = state;
  if (direction === 'left') {
    x -= o === 0 ? 2 : 1;
    if (o !== 2) o = o === 0 ? 1 : 0;
  } else if (direction === 'right') {
    x += o === 1 ? 2 : 1;
    if (o !== 2) o = o === 0 ? 1 : 0;
  } else if (direction === 'up') {
    y -= o === 0 ? 2 : 1;
    if (o !== 1) o = o === 0 ? 2 : 0;
  } else if (direction === 'down') {
    y += o === 2 ? 2 : 1;
    if (o !== 1) o = o === 0 ? 2 : 0;
  } else return null;

  let mask = state.mask || 0;
  const next = { x, y, o, mask };
  const before = new Set(occupied(state).map(p => cellKey(...p)));
  const after = occupied(next);
  const afterKeys = new Set(after.map(p => cellKey(...p)));
  for (const button of level.switches || []) {
    const key = cellKey(...button.at);
    if (afterKeys.has(key) && !before.has(key)) mask ^= 1 << button.bit;
  }
  next.mask = mask;
  const data = geometry(level);
  for (const [tx, ty] of after) {
    const key = cellKey(tx, ty);
    if (!data.tiles.has(key)) return null;
    if (data.bridges.has(key) && !(mask & (1 << data.bridges.get(key)))) return null;
    if (o === 0 && data.fragile.has(key)) return null;
  }
  return next;
}

export function isWin(level, state) {
  return state.o === 0 && state.x === level.goal[0] && state.y === level.goal[1];
}

/** Breadth-first search also powers contextual hints from the current state. */
export function solve(level, state = level.start) {
  if (isWin(level, state)) return [];
  const first = { ...state, mask: state.mask || 0 };
  const queue = [first];
  const parents = new Map([[stateKey(first), null]]);
  for (let head = 0; head < queue.length; head++) {
    const current = queue[head];
    for (const direction of DIRECTIONS) {
      const next = move(level, current, direction);
      if (!next) continue;
      const key = stateKey(next);
      if (parents.has(key)) continue;
      parents.set(key, { previous: stateKey(current), direction });
      if (isWin(level, next)) {
        const result = [];
        let cursor = key;
        while (parents.get(cursor)) {
          const step = parents.get(cursor);
          result.push(step.direction);
          cursor = step.previous;
        }
        return result.reverse();
      }
      queue.push(next);
    }
  }
  return null;
}

